-- LUCRA · planos (Básico, Médio, Premium). Uma instrução por linha e pode rodar de novo.
-- O plano fica na clínica e só você muda (pelo Table Editor do Supabase): o app não consegue alterar.
alter table public.clinicas add column if not exists plano text not null default 'basico';
do $$ begin alter table public.clinicas add constraint clinicas_plano_chk check (plano in ('basico','medio','premium')); exception when duplicate_object then null; end $$;
update public.clinicas set plano = 'premium' where plano = 'basico';
create or replace function public.convidar(p_cid uuid, p_email text, p_papel text) returns void language plpgsql security definer set search_path = public as $$ declare lim int; n int; begin if meu_papel(p_cid) is distinct from 'dono' then raise exception 'so_dono'; end if; select case plano when 'basico' then 1 when 'medio' then 3 else 1000 end into lim from clinicas where id = p_cid; select (select count(*) from membros where clinica_id = p_cid) + (select count(*) from convites where clinica_id = p_cid and email <> lower(trim(p_email))) into n; if n >= lim then raise exception 'limite_plano'; end if; insert into convites (clinica_id, email, papel) values (p_cid, lower(trim(p_email)), p_papel) on conflict (clinica_id, email) do update set papel = excluded.papel; end $$;
create or replace function public.criar_unidade(p_nome text, p_area text, p_pessoa text) returns uuid language plpgsql security definer set search_path = public as $$ declare cid uuid; begin if auth.uid() is null then raise exception 'sem_login'; end if; if not exists (select 1 from membros m join clinicas c on c.id = m.clinica_id where m.user_id = auth.uid() and m.papel = 'dono' and c.plano = 'premium') then raise exception 'so_premium'; end if; if (select count(*) from membros where user_id = auth.uid() and papel = 'dono') >= 10 then raise exception 'limite_unidades'; end if; insert into clinicas (nome, area, plano) values (coalesce(p_nome, ''), p_area, 'premium') returning id into cid; insert into membros (clinica_id, user_id, papel, nome, email) values (cid, auth.uid(), 'dono', coalesce(p_pessoa, ''), coalesce(auth.jwt()->>'email', '')); insert into dados (clinica_id) values (cid); insert into clinico (clinica_id) values (cid); return cid; end $$;
